//! Filter expression parser and evaluator.
//!
//! Parses the pandas-eval query strings generated by the Python Filter DSL
//! into an AST, then evaluates against Polars DataFrames.
//!
//! Supported patterns (all generated by schema.py):
//!   "(type == 'put') & (ask > 0)"
//!   "(underlying == 'SPX') & (dte >= 60) & (dte <= 120)"
//!   "(strike >= underlying_last * 1.02)"
//!   "dte <= 30"

use polars::prelude::*;
use thiserror::Error;

#[derive(Error, Debug)]
pub enum FilterError {
    #[error("parse error: {0}")]
    Parse(String),
    #[error("polars error: {0}")]
    Polars(#[from] PolarsError),
}

/// A parsed value literal.
#[derive(Debug, Clone, PartialEq)]
pub enum Value {
    Int(i64),
    Float(f64),
    Str(String),
    Column(String),
}

/// Comparison operator.
#[derive(Debug, Clone, Copy, PartialEq)]
pub enum CmpOp {
    Eq,
    Ne,
    Lt,
    Le,
    Gt,
    Ge,
}

/// Arithmetic operator for column expressions.
#[derive(Debug, Clone, Copy, PartialEq)]
pub enum ArithOp {
    Add,
    Sub,
    Mul,
    Div,
}

/// Arithmetic over columns and numeric literals.
#[derive(Debug, Clone, PartialEq)]
pub enum Arith {
    Val(Value),
    Neg(Box<Arith>),
    Bin(Box<Arith>, ArithOp, Box<Arith>),
}

/// Compiled filter expression AST.
#[derive(Debug, Clone, PartialEq)]
pub enum FilterExpr {
    Cmp(String, CmpOp, Value),
    /// column <arith_op> value <cmp_op> value
    /// e.g. strike >= underlying_last * 1.02
    ColArith(String, ArithOp, Value, CmpOp, Value),
    /// Any other numeric comparison, e.g. `0.9 * underlying_last <= strike`
    /// or `(strike - 5) / underlying_last > 0.8`.
    Compare(Arith, CmpOp, Arith),
    And(Box<FilterExpr>, Box<FilterExpr>),
    Or(Box<FilterExpr>, Box<FilterExpr>),
    Not(Box<FilterExpr>),
}

/// Tokenizer for filter expressions.
#[derive(Debug, Clone, PartialEq)]
enum Token {
    Ident(String),
    StrLit(String),
    IntLit(i64),
    FloatLit(f64),
    Eq,    // ==
    Ne,    // !=
    Lt,    // <
    Le,    // <=
    Gt,    // >
    Ge,    // >=
    And,   // &
    Or,    // |
    Not,   // !
    LParen,
    RParen,
    Plus,
    Minus,
    Star,
    Slash,
}

fn tokenize(input: &str) -> Result<Vec<Token>, FilterError> {
    let mut tokens = Vec::new();
    let chars: Vec<char> = input.chars().collect();
    let mut i = 0;

    while i < chars.len() {
        match chars[i] {
            ' ' | '\t' | '\n' => i += 1,
            '(' => { tokens.push(Token::LParen); i += 1; }
            ')' => { tokens.push(Token::RParen); i += 1; }
            '&' => { tokens.push(Token::And); i += 1; }
            '|' => { tokens.push(Token::Or); i += 1; }
            '+' => { tokens.push(Token::Plus); i += 1; }
            '-' => { tokens.push(Token::Minus); i += 1; }
            '*' => { tokens.push(Token::Star); i += 1; }
            '/' => { tokens.push(Token::Slash); i += 1; }
            '!' => {
                if i + 1 < chars.len() && chars[i + 1] == '=' {
                    tokens.push(Token::Ne);
                    i += 2;
                } else {
                    tokens.push(Token::Not);
                    i += 1;
                }
            }
            '=' => {
                if i + 1 < chars.len() && chars[i + 1] == '=' {
                    tokens.push(Token::Eq);
                    i += 2;
                } else {
                    return Err(FilterError::Parse(format!("unexpected '=' at {i}")));
                }
            }
            '<' => {
                if i + 1 < chars.len() && chars[i + 1] == '=' {
                    tokens.push(Token::Le);
                    i += 2;
                } else {
                    tokens.push(Token::Lt);
                    i += 1;
                }
            }
            '>' => {
                if i + 1 < chars.len() && chars[i + 1] == '=' {
                    tokens.push(Token::Ge);
                    i += 2;
                } else {
                    tokens.push(Token::Gt);
                    i += 1;
                }
            }
            '\'' | '"' => {
                let quote = chars[i];
                i += 1;
                let start = i;
                while i < chars.len() && chars[i] != quote {
                    i += 1;
                }
                let s: String = chars[start..i].iter().collect();
                tokens.push(Token::StrLit(s));
                i += 1; // skip closing quote
            }
            c if c.is_ascii_digit() || c == '.' => {
                let start = i;
                let mut has_dot = c == '.';
                let mut has_exp = false;
                i += 1;
                while i < chars.len() && (chars[i].is_ascii_digit() || chars[i] == '.') {
                    if chars[i] == '.' { has_dot = true; }
                    i += 1;
                }
                // Scientific notation: e/E followed by optional +/- and digits
                if i < chars.len() && (chars[i] == 'e' || chars[i] == 'E') {
                    has_exp = true;
                    i += 1;
                    if i < chars.len() && (chars[i] == '+' || chars[i] == '-') {
                        i += 1;
                    }
                    while i < chars.len() && chars[i].is_ascii_digit() {
                        i += 1;
                    }
                }
                let num_str: String = chars[start..i].iter().collect();
                if has_dot || has_exp {
                    tokens.push(Token::FloatLit(
                        num_str.parse().map_err(|e| FilterError::Parse(format!("{e}")))?,
                    ));
                } else {
                    tokens.push(Token::IntLit(
                        num_str.parse().map_err(|e| FilterError::Parse(format!("{e}")))?,
                    ));
                }
            }
            c if c.is_ascii_alphabetic() || c == '_' => {
                let start = i;
                i += 1;
                while i < chars.len() && (chars[i].is_ascii_alphanumeric() || chars[i] == '_') {
                    i += 1;
                }
                let ident: String = chars[start..i].iter().collect();
                tokens.push(Token::Ident(ident));
            }
            c => return Err(FilterError::Parse(format!("unexpected char '{c}' at {i}"))),
        }
    }

    Ok(tokens)
}

/// Recursive descent parser.
struct Parser {
    tokens: Vec<Token>,
    pos: usize,
}

impl Parser {
    fn new(tokens: Vec<Token>) -> Self {
        Self { tokens, pos: 0 }
    }

    fn peek(&self) -> Option<&Token> {
        self.tokens.get(self.pos)
    }

    fn advance(&mut self) -> Option<Token> {
        let tok = self.tokens.get(self.pos)?.clone();
        self.pos += 1;
        Some(tok)
    }

    fn expect(&mut self, expected: &Token) -> Result<(), FilterError> {
        let tok = self.advance().ok_or_else(|| FilterError::Parse("unexpected end".into()))?;
        if &tok != expected {
            return Err(FilterError::Parse(format!("expected {expected:?}, got {tok:?}")));
        }
        Ok(())
    }

    /// expr = or_expr
    fn parse_expr(&mut self) -> Result<FilterExpr, FilterError> {
        self.parse_or()
    }

    /// or_expr = and_expr ( '|' and_expr )*
    fn parse_or(&mut self) -> Result<FilterExpr, FilterError> {
        let mut left = self.parse_and()?;
        while matches!(self.peek(), Some(Token::Or)) {
            self.advance();
            let right = self.parse_and()?;
            left = FilterExpr::Or(Box::new(left), Box::new(right));
        }
        Ok(left)
    }

    /// and_expr = unary ( '&' unary )*
    fn parse_and(&mut self) -> Result<FilterExpr, FilterError> {
        let mut left = self.parse_unary()?;
        while matches!(self.peek(), Some(Token::And)) {
            self.advance();
            let right = self.parse_unary()?;
            left = FilterExpr::And(Box::new(left), Box::new(right));
        }
        Ok(left)
    }

    /// unary = '!' unary | primary
    fn parse_unary(&mut self) -> Result<FilterExpr, FilterError> {
        if matches!(self.peek(), Some(Token::Not)) {
            self.advance();
            let inner = self.parse_unary()?;
            return Ok(FilterExpr::Not(Box::new(inner)));
        }
        self.parse_primary()
    }

    /// primary = comparison | '(' expr ')'
    ///
    /// A leading '(' is ambiguous: `(strike - 5) > x` is a comparison whose
    /// left side is parenthesized, `(a > 1) & (b < 2)` a boolean group. Try
    /// the comparison first and fall back to the group.
    fn parse_primary(&mut self) -> Result<FilterExpr, FilterError> {
        let start = self.pos;
        match self.parse_comparison() {
            Ok(cmp) => Ok(cmp),
            Err(err) => {
                self.pos = start;
                if !matches!(self.peek(), Some(Token::LParen)) {
                    return Err(err);
                }
                self.advance();
                let expr = self.parse_expr()?;
                self.expect(&Token::RParen)?;
                Ok(expr)
            }
        }
    }

    /// comparison = arith cmp_op arith
    fn parse_comparison(&mut self) -> Result<FilterExpr, FilterError> {
        let left = self.parse_sum()?;
        let cmp = self.parse_cmp_op()?;
        let right = self.parse_sum()?;
        lower_comparison(left, cmp, right)
    }

    /// sum = term (('+' | '-') term)*
    fn parse_sum(&mut self) -> Result<Arith, FilterError> {
        let mut left = self.parse_term()?;
        loop {
            let op = match self.peek() {
                Some(Token::Plus) => ArithOp::Add,
                Some(Token::Minus) => ArithOp::Sub,
                _ => return Ok(left),
            };
            self.advance();
            let right = self.parse_term()?;
            left = Arith::Bin(Box::new(left), op, Box::new(right));
        }
    }

    /// term = factor (('*' | '/') factor)*
    fn parse_term(&mut self) -> Result<Arith, FilterError> {
        let mut left = self.parse_factor()?;
        loop {
            let op = match self.peek() {
                Some(Token::Star) => ArithOp::Mul,
                Some(Token::Slash) => ArithOp::Div,
                _ => return Ok(left),
            };
            self.advance();
            let right = self.parse_factor()?;
            left = Arith::Bin(Box::new(left), op, Box::new(right));
        }
    }

    /// factor = '-' factor | '(' sum ')' | ident | number | string
    fn parse_factor(&mut self) -> Result<Arith, FilterError> {
        let tok = self.advance().ok_or_else(|| FilterError::Parse("unexpected end".into()))?;
        match tok {
            Token::Ident(name) => Ok(Arith::Val(Value::Column(name))),
            Token::IntLit(n) => Ok(Arith::Val(Value::Int(n))),
            Token::FloatLit(f) => Ok(Arith::Val(Value::Float(f))),
            Token::StrLit(s) => Ok(Arith::Val(Value::Str(s))),
            Token::Minus => match self.parse_factor()? {
                Arith::Val(Value::Int(n)) => Ok(Arith::Val(Value::Int(-n))),
                Arith::Val(Value::Float(f)) => Ok(Arith::Val(Value::Float(-f))),
                Arith::Val(Value::Str(_)) => Err(FilterError::Parse("cannot negate a string".into())),
                other => Ok(Arith::Neg(Box::new(other))),
            },
            Token::LParen => {
                let inner = self.parse_sum()?;
                self.expect(&Token::RParen)?;
                Ok(inner)
            }
            t => Err(FilterError::Parse(format!("unexpected token in value: {t:?}"))),
        }
    }

    fn parse_cmp_op(&mut self) -> Result<CmpOp, FilterError> {
        match self.advance() {
            Some(Token::Eq) => Ok(CmpOp::Eq),
            Some(Token::Ne) => Ok(CmpOp::Ne),
            Some(Token::Lt) => Ok(CmpOp::Lt),
            Some(Token::Le) => Ok(CmpOp::Le),
            Some(Token::Gt) => Ok(CmpOp::Gt),
            Some(Token::Ge) => Ok(CmpOp::Ge),
            t => Err(FilterError::Parse(format!("expected comparison op, got {t:?}"))),
        }
    }
}

/// Map a parsed comparison onto the simplest AST node that represents it:
/// `Cmp` / `ColArith` for the common shapes (and the fast paths that match on
/// them), `Compare` for anything else. Strings only compare by (in)equality
/// against a plain column.
fn lower_comparison(left: Arith, cmp: CmpOp, right: Arith) -> Result<FilterExpr, FilterError> {
    use Arith::{Bin, Val};
    let is_str = |a: &Arith| matches!(a, Val(Value::Str(_)));
    if is_str(&left) || is_str(&right) {
        return match (left, right) {
            (Val(Value::Column(c)), Val(v @ Value::Str(_))) | (Val(v @ Value::Str(_)), Val(Value::Column(c)))
                if matches!(cmp, CmpOp::Eq | CmpOp::Ne) => Ok(FilterExpr::Cmp(c, cmp, v)),
            _ => Err(FilterError::Parse("strings only compare with == / != against a column".into())),
        };
    }
    let simple = |a: &Arith| matches!(a, Val(_));
    Ok(match (left, right) {
        (Val(Value::Column(c)), Val(v)) => FilterExpr::Cmp(c, cmp, v),
        (Val(v), Val(Value::Column(c))) => FilterExpr::Cmp(c, flip_cmp(cmp), v),
        (Bin(l, op, r), rhs) if matches!(*l, Val(Value::Column(_))) && simple(&r) && simple(&rhs) => {
            match (*l, *r, rhs) {
                (Val(Value::Column(c)), Val(operand), Val(v)) => FilterExpr::ColArith(c, op, operand, cmp, v),
                _ => unreachable!(),
            }
        }
        (lhs, Bin(l, op, r)) if matches!(*l, Val(Value::Column(_))) && simple(&r) && simple(&lhs) => {
            match (*l, *r, lhs) {
                (Val(Value::Column(c)), Val(operand), Val(v)) => {
                    FilterExpr::ColArith(c, op, operand, flip_cmp(cmp), v)
                }
                _ => unreachable!(),
            }
        }
        (lhs, rhs) => FilterExpr::Compare(lhs, cmp, rhs),
    })
}

fn flip_cmp(op: CmpOp) -> CmpOp {
    match op {
        CmpOp::Lt => CmpOp::Gt,
        CmpOp::Le => CmpOp::Ge,
        CmpOp::Gt => CmpOp::Lt,
        CmpOp::Ge => CmpOp::Le,
        other => other,
    }
}

/// Parse a query string into a FilterExpr AST.
pub fn parse(query: &str) -> Result<FilterExpr, FilterError> {
    let tokens = tokenize(query)?;
    let mut parser = Parser::new(tokens);
    let expr = parser.parse_expr()?;
    if parser.pos != parser.tokens.len() {
        return Err(FilterError::Parse(format!(
            "unexpected tokens after position {}",
            parser.pos
        )));
    }
    Ok(expr)
}

/// Convert a FilterExpr to a Polars Expr for lazy evaluation.
pub fn to_polars_expr(filter: &FilterExpr) -> Expr {
    match filter {
        FilterExpr::Cmp(column, op, value) => {
            let c = col(column.as_str());
            let v = value_to_lit(value);
            apply_cmp(c, *op, v)
        }
        FilterExpr::ColArith(column, arith_op, arith_val, cmp_op, cmp_val) => {
            let c = col(column.as_str());
            let av = value_to_lit(arith_val);
            let arith_expr = match arith_op {
                ArithOp::Add => c + av,
                ArithOp::Sub => c - av,
                ArithOp::Mul => c * av,
                ArithOp::Div => c / av,
            };
            let cv = value_to_lit(cmp_val);
            apply_cmp(arith_expr, *cmp_op, cv)
        }
        FilterExpr::Compare(left, op, right) => {
            apply_cmp(arith_to_polars(left), *op, arith_to_polars(right))
        }
        FilterExpr::And(left, right) => {
            to_polars_expr(left).and(to_polars_expr(right))
        }
        FilterExpr::Or(left, right) => {
            to_polars_expr(left).or(to_polars_expr(right))
        }
        FilterExpr::Not(inner) => {
            to_polars_expr(inner).not()
        }
    }
}

fn arith_to_polars(a: &Arith) -> Expr {
    match a {
        Arith::Val(v) => value_to_lit(v),
        Arith::Neg(inner) => lit(0.0) - arith_to_polars(inner),
        Arith::Bin(l, op, r) => {
            let (l, r) = (arith_to_polars(l), arith_to_polars(r));
            match op {
                ArithOp::Add => l + r,
                ArithOp::Sub => l - r,
                ArithOp::Mul => l * r,
                ArithOp::Div => l / r,
            }
        }
    }
}

fn value_to_lit(value: &Value) -> Expr {
    match value {
        // Always use f64 for numeric literals to avoid Int128 issues in polars 0.48
        Value::Int(n) => lit(*n as f64),
        Value::Float(f) => lit(*f),
        Value::Str(s) => lit(s.as_str()),
        Value::Column(name) => col(name.as_str()),
    }
}

fn apply_cmp(left: Expr, op: CmpOp, right: Expr) -> Expr {
    match op {
        CmpOp::Eq => left.eq(right),
        CmpOp::Ne => left.neq(right),
        CmpOp::Lt => left.lt(right),
        CmpOp::Le => left.lt_eq(right),
        CmpOp::Gt => left.gt(right),
        CmpOp::Ge => left.gt_eq(right),
    }
}

/// A compiled filter: parsed once, evaluated many times.
pub struct CompiledFilter {
    pub expr: FilterExpr,
    pub polars_expr: Expr,
}

impl CompiledFilter {
    pub fn new(query: &str) -> Result<Self, FilterError> {
        let expr = parse(query)?;
        let polars_expr = to_polars_expr(&expr);
        Ok(Self { expr, polars_expr })
    }

    pub fn apply(&self, df: &DataFrame) -> PolarsResult<DataFrame> {
        let mask = df
            .clone()
            .lazy()
            .select([self.polars_expr.clone().alias("_mask")])
            .collect()?;
        let bool_mask = mask.column("_mask")?.bool()?.clone();
        df.filter(&bool_mask)
    }

    /// Evaluate filter against a single row — O(1) per comparison, no Polars overhead.
    #[inline]
    pub fn eval_row(&self, df: &DataFrame, row_idx: usize) -> bool {
        eval_expr_row(&self.expr, df, row_idx)
    }
}

/// Read a numeric value from a column at a given row index.
#[inline]
fn read_f64(col: &Column, row: usize) -> Option<f64> {
    if let Ok(ca) = col.f64() {
        return ca.get(row);
    }
    if let Ok(ca) = col.i64() {
        return ca.get(row).map(|v| v as f64);
    }
    if let Ok(ca) = col.i32() {
        return ca.get(row).map(|v| v as f64);
    }
    None
}

/// Read a string value from a column at a given row index.
#[inline]
fn read_str(col: &Column, row: usize) -> Option<&str> {
    col.str().ok().and_then(|ca| ca.get(row))
}

/// Compare two f64 values with the given operator.
#[inline]
fn cmp_f64(lhs: f64, op: CmpOp, rhs: f64) -> bool {
    match op {
        CmpOp::Eq => (lhs - rhs).abs() < f64::EPSILON,
        CmpOp::Ne => (lhs - rhs).abs() >= f64::EPSILON,
        CmpOp::Lt => lhs < rhs,
        CmpOp::Le => lhs <= rhs,
        CmpOp::Gt => lhs > rhs,
        CmpOp::Ge => lhs >= rhs,
    }
}

/// Resolve a Value to f64 given a DataFrame and row index.
#[inline]
fn resolve_f64(val: &Value, df: &DataFrame, row: usize) -> Option<f64> {
    match val {
        Value::Int(n) => Some(*n as f64),
        Value::Float(f) => Some(*f),
        Value::Column(name) => df.column(name).ok().and_then(|c| read_f64(c, row)),
        Value::Str(_) => None,
    }
}

fn eval_arith_row(a: &Arith, df: &DataFrame, row: usize) -> Option<f64> {
    match a {
        Arith::Val(v) => resolve_f64(v, df, row),
        Arith::Neg(inner) => eval_arith_row(inner, df, row).map(|v| -v),
        Arith::Bin(l, op, r) => {
            let (l, r) = (eval_arith_row(l, df, row)?, eval_arith_row(r, df, row)?);
            Some(match op {
                ArithOp::Add => l + r,
                ArithOp::Sub => l - r,
                ArithOp::Mul => l * r,
                ArithOp::Div => l / r,
            })
        }
    }
}

/// Evaluate a filter expression against a single row directly.
fn eval_expr_row(expr: &FilterExpr, df: &DataFrame, row: usize) -> bool {
    match expr {
        FilterExpr::Cmp(col_name, op, val) => {
            let col = match df.column(col_name) {
                Ok(c) => c,
                Err(_) => return false,
            };
            match val {
                Value::Str(s) => {
                    match read_str(col, row) {
                        Some(cell) => match op {
                            CmpOp::Eq => cell == s.as_str(),
                            CmpOp::Ne => cell != s.as_str(),
                            _ => false,
                        },
                        None => false,
                    }
                }
                _ => {
                    match (read_f64(col, row), resolve_f64(val, df, row)) {
                        (Some(lhs), Some(rhs)) => cmp_f64(lhs, *op, rhs),
                        _ => false,
                    }
                }
            }
        }
        FilterExpr::ColArith(col_name, arith_op, arith_val, cmp_op, cmp_val) => {
            let col = match df.column(col_name) {
                Ok(c) => c,
                Err(_) => return false,
            };
            let base = match read_f64(col, row) {
                Some(v) => v,
                None => return false,
            };
            let operand = match resolve_f64(arith_val, df, row) {
                Some(v) => v,
                None => return false,
            };
            let arith_result = match arith_op {
                ArithOp::Add => base + operand,
                ArithOp::Sub => base - operand,
                ArithOp::Mul => base * operand,
                ArithOp::Div => base / operand,
            };
            let rhs = match resolve_f64(cmp_val, df, row) {
                Some(v) => v,
                None => return false,
            };
            cmp_f64(arith_result, *cmp_op, rhs)
        }
        FilterExpr::Compare(l, op, r) => {
            match (eval_arith_row(l, df, row), eval_arith_row(r, df, row)) {
                (Some(lhs), Some(rhs)) => cmp_f64(lhs, *op, rhs),
                _ => false,
            }
        }
        FilterExpr::And(l, r) => eval_expr_row(l, df, row) && eval_expr_row(r, df, row),
        FilterExpr::Or(l, r) => eval_expr_row(l, df, row) || eval_expr_row(r, df, row),
        FilterExpr::Not(inner) => !eval_expr_row(inner, df, row),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn parse_simple_eq() {
        let expr = parse("type == 'put'").unwrap();
        assert_eq!(
            expr,
            FilterExpr::Cmp("type".into(), CmpOp::Eq, Value::Str("put".into()))
        );
    }

    #[test]
    fn parse_simple_gte() {
        let expr = parse("dte >= 60").unwrap();
        assert_eq!(
            expr,
            FilterExpr::Cmp("dte".into(), CmpOp::Ge, Value::Int(60))
        );
    }

    #[test]
    fn parse_and() {
        let expr = parse("(type == 'put') & (ask > 0)").unwrap();
        match expr {
            FilterExpr::And(left, right) => {
                assert_eq!(
                    *left,
                    FilterExpr::Cmp("type".into(), CmpOp::Eq, Value::Str("put".into()))
                );
                assert_eq!(
                    *right,
                    FilterExpr::Cmp("ask".into(), CmpOp::Gt, Value::Int(0))
                );
            }
            _ => panic!("expected And"),
        }
    }

    #[test]
    fn parse_col_arith() {
        // "strike >= underlying_last * 1.02" flips to:
        // ColArith("underlying_last", Mul, 1.02, Le, Column("strike"))
        let expr = parse("strike >= underlying_last * 1.02").unwrap();
        match expr {
            FilterExpr::ColArith(ref col, ArithOp::Mul, Value::Float(f), CmpOp::Le, Value::Column(ref rhs)) => {
                assert_eq!(col, "underlying_last");
                assert!((f - 1.02).abs() < 1e-10);
                assert_eq!(rhs, "strike");
            }
            _ => panic!("expected ColArith, got {expr:?}"),
        }
    }

    #[test]
    fn parse_chained_and() {
        let expr = parse("(underlying == 'SPX') & (dte >= 60) & (dte <= 120)").unwrap();
        // Should be And(And(eq, gte), lte)
        match expr {
            FilterExpr::And(_, _) => {} // OK
            _ => panic!("expected chained And"),
        }
    }

    #[test]
    fn compiled_filter_apply() {
        let df = DataFrame::new(vec![
            Column::new("type".into(), &["call", "put", "put"]),
            Column::new("ask".into(), &[1.0f64, 2.0, 0.0]),
        ])
        .unwrap();

        let f = CompiledFilter::new("(type == 'put') & (ask > 0)").unwrap();
        let result = f.apply(&df).unwrap();
        assert_eq!(result.height(), 1);
    }

    #[test]
    fn compiled_filter_dte_range() {
        let df = DataFrame::new(vec![
            Column::new("underlying".into(), &["SPX", "SPX", "AAPL", "SPX"]),
            Column::new("dte".into(), &[30i32, 90, 90, 150]),
        ])
        .unwrap();

        let f = CompiledFilter::new("(underlying == 'SPX') & (dte >= 60) & (dte <= 120)").unwrap();
        let result = f.apply(&df).unwrap();
        assert_eq!(result.height(), 1); // Only SPX with dte=90
    }

    #[test]
    fn parse_scientific_notation() {
        let expr = parse("ask > 1e-5").unwrap();
        match expr {
            FilterExpr::Cmp(col, CmpOp::Gt, Value::Float(f)) => {
                assert_eq!(col, "ask");
                assert!((f - 1e-5).abs() < 1e-15);
            }
            _ => panic!("expected Cmp with float, got {expr:?}"),
        }
    }

    #[test]
    fn parse_scientific_notation_positive_exp() {
        let expr = parse("strike >= 1.5E3").unwrap();
        match expr {
            FilterExpr::Cmp(col, CmpOp::Ge, Value::Float(f)) => {
                assert_eq!(col, "strike");
                assert!((f - 1500.0).abs() < 1e-10);
            }
            _ => panic!("expected Cmp with float, got {expr:?}"),
        }
    }

    #[test]
    fn parse_scientific_notation_no_sign() {
        let expr = parse("delta >= 1e2").unwrap();
        match expr {
            FilterExpr::Cmp(_, CmpOp::Ge, Value::Float(f)) => {
                assert!((f - 100.0).abs() < 1e-10);
            }
            _ => panic!("expected float, got {expr:?}"),
        }
    }

    #[test]
    fn compiled_filter_scientific_notation() {
        let df = DataFrame::new(vec![
            Column::new("ask".into(), &[0.0f64, 0.00001, 0.1, 5.0]),
        ]).unwrap();

        let f = CompiledFilter::new("ask > 1e-3").unwrap();
        let result = f.apply(&df).unwrap();
        assert_eq!(result.height(), 2); // 0.1 and 5.0
    }

    #[test]
    fn parse_negative_float_literal() {
        let expr = parse("delta >= -0.25").unwrap();
        assert_eq!(
            expr,
            FilterExpr::Cmp("delta".into(), CmpOp::Ge, Value::Float(-0.25))
        );
    }

    #[test]
    fn parse_negative_int_literal() {
        let expr = parse("dte >= -30").unwrap();
        assert_eq!(
            expr,
            FilterExpr::Cmp("dte".into(), CmpOp::Ge, Value::Int(-30))
        );
    }

    #[test]
    fn parse_negative_delta_range() {
        // The exact pattern that fails for Cash-Secured Put / Short Strangle
        let expr = parse("(delta >= -0.30) & (delta <= -0.15)").unwrap();
        match expr {
            FilterExpr::And(left, right) => {
                assert_eq!(
                    *left,
                    FilterExpr::Cmp("delta".into(), CmpOp::Ge, Value::Float(-0.30))
                );
                assert_eq!(
                    *right,
                    FilterExpr::Cmp("delta".into(), CmpOp::Le, Value::Float(-0.15))
                );
            }
            _ => panic!("expected And, got {expr:?}"),
        }
    }

    #[test]
    fn compiled_filter_negative_delta() {
        let df = DataFrame::new(vec![
            Column::new("delta".into(), &[-0.40f64, -0.25, -0.15, -0.05, 0.10]),
        ]).unwrap();

        let f = CompiledFilter::new("(delta >= -0.30) & (delta <= -0.10)").unwrap();
        let result = f.apply(&df).unwrap();
        assert_eq!(result.height(), 2); // -0.25 and -0.15
    }

    // --- eval_row tests ---

    #[test]
    fn eval_row_simple_eq() {
        let df = DataFrame::new(vec![
            Column::new("type".into(), &["call", "put", "put"]),
            Column::new("ask".into(), &[1.0f64, 2.0, 0.0]),
        ]).unwrap();

        let f = CompiledFilter::new("type == 'put'").unwrap();
        assert!(!f.eval_row(&df, 0)); // call
        assert!(f.eval_row(&df, 1));  // put
        assert!(f.eval_row(&df, 2));  // put
    }

    #[test]
    fn eval_row_and_filter() {
        let df = DataFrame::new(vec![
            Column::new("type".into(), &["call", "put", "put"]),
            Column::new("ask".into(), &[1.0f64, 2.0, 0.0]),
        ]).unwrap();

        let f = CompiledFilter::new("(type == 'put') & (ask > 0)").unwrap();
        assert!(!f.eval_row(&df, 0)); // call
        assert!(f.eval_row(&df, 1));  // put, ask=2
        assert!(!f.eval_row(&df, 2)); // put, ask=0
    }

    #[test]
    fn eval_row_col_arith() {
        let df = DataFrame::new(vec![
            Column::new("strike".into(), &[110.0f64, 95.0, 105.0]),
            Column::new("underlying_last".into(), &[100.0f64, 100.0, 100.0]),
        ]).unwrap();

        // strike >= underlying_last * 1.02 → ColArith("underlying_last", Mul, 1.02, Le, Column("strike"))
        let f = CompiledFilter::new("strike >= underlying_last * 1.02").unwrap();
        assert!(f.eval_row(&df, 0));  // 110 >= 102
        assert!(!f.eval_row(&df, 1)); // 95 < 102
        assert!(f.eval_row(&df, 2));  // 105 >= 102
    }

    #[test]
    fn eval_row_negative_delta() {
        let df = DataFrame::new(vec![
            Column::new("delta".into(), &[-0.40f64, -0.25, -0.15, -0.05, 0.10]),
        ]).unwrap();

        let f = CompiledFilter::new("(delta >= -0.30) & (delta <= -0.10)").unwrap();
        assert!(!f.eval_row(&df, 0)); // -0.40
        assert!(f.eval_row(&df, 1));  // -0.25
        assert!(f.eval_row(&df, 2));  // -0.15
        assert!(!f.eval_row(&df, 3)); // -0.05
        assert!(!f.eval_row(&df, 4)); // 0.10
    }

    #[test]
    fn eval_row_matches_apply() {
        // Verify eval_row matches apply for all rows
        let df = DataFrame::new(vec![
            Column::new("underlying".into(), &["SPX", "SPX", "AAPL", "SPX"]),
            Column::new("dte".into(), &[30i32, 90, 90, 150]),
        ]).unwrap();

        let f = CompiledFilter::new("(underlying == 'SPX') & (dte >= 60) & (dte <= 120)").unwrap();
        let apply_result = f.apply(&df).unwrap();
        assert_eq!(apply_result.height(), 1);

        // eval_row should match
        assert!(!f.eval_row(&df, 0)); // SPX, dte=30
        assert!(f.eval_row(&df, 1));  // SPX, dte=90
        assert!(!f.eval_row(&df, 2)); // AAPL
        assert!(!f.eval_row(&df, 3)); // SPX, dte=150
    }

    fn strikes_df() -> DataFrame {
        DataFrame::new(vec![
            Column::new("strike".into(), &[70.0f64, 80.0, 90.0, 95.0]),
            Column::new("underlying_last".into(), &[100.0f64, 100.0, 100.0, 100.0]),
            Column::new("type".into(), &["put", "call", "put", "put"]),
        ]).unwrap()
    }

    /// Rows where `query` holds, by both evaluation paths (they must agree).
    fn matches(query: &str) -> Vec<usize> {
        let df = strikes_df();
        let f = CompiledFilter::new(query).unwrap();
        let by_row: Vec<usize> = (0..df.height()).filter(|&r| f.eval_row(&df, r)).collect();
        let strikes = f.apply(&df).unwrap().column("strike").unwrap().f64().unwrap()
            .into_no_null_iter().collect::<Vec<_>>();
        let all = df.column("strike").unwrap().f64().unwrap().into_no_null_iter().collect::<Vec<_>>();
        let by_polars: Vec<usize> = strikes.iter().map(|k| all.iter().position(|a| a == k).unwrap()).collect();
        assert_eq!(by_row, by_polars, "eval_row and apply disagree for {query:?}");
        by_row
    }

    #[test]
    fn literal_times_column_on_the_left() {
        // Python's 0.9 * schema.underlying_last emits the literal first.
        assert_eq!(matches("0.9 * underlying_last <= strike"), vec![2, 3]);
        assert_eq!(matches("strike >= 0.9 * underlying_last"), vec![2, 3]);
    }

    #[test]
    fn chained_arithmetic_respects_precedence() {
        // 100 * 0.9 - 5 = 85, not 100 * (0.9 - 5)
        assert_eq!(matches("strike >= underlying_last * 0.9 - 5"), vec![2, 3]);
        assert_eq!(matches("strike - 5 >= underlying_last * 0.7"), vec![1, 2, 3]);
    }

    #[test]
    fn parenthesized_arithmetic_vs_boolean_groups() {
        assert_eq!(matches("(strike - 10) / underlying_last > 0.75"), vec![2, 3]);
        assert_eq!(matches("((strike > 75) & (strike < 92)) | (strike == 70)"), vec![0, 1, 2]);
        assert_eq!(matches("(strike + 0) > 85 & (type == 'put')"), vec![2, 3]);
    }

    #[test]
    fn unary_minus_on_expressions() {
        assert_eq!(matches("-strike < -85"), vec![2, 3]);
        assert_eq!(matches("-(strike - 100) >= 10"), vec![0, 1, 2]);
    }

    #[test]
    fn string_not_equal_and_errors() {
        assert_eq!(matches("type != 'put'"), vec![1]);
        assert!(CompiledFilter::new("type > 'put'").is_err());
        assert!(CompiledFilter::new("strike >= ").is_err());
        assert!(CompiledFilter::new("strike >= underlying_last * ").is_err());
    }

    #[test]
    fn simple_shapes_keep_their_fast_nodes() {
        assert!(matches!(parse("strike >= 80").unwrap(), FilterExpr::Cmp(..)));
        assert!(matches!(parse("80 <= strike").unwrap(), FilterExpr::Cmp(..)));
        assert!(matches!(parse("strike >= underlying_last * 0.9").unwrap(), FilterExpr::ColArith(..)));
        assert!(matches!(parse("0.9 * underlying_last <= strike").unwrap(), FilterExpr::Compare(..)));
    }
}
